def diff(got, want, where=''):
    if type(got) != type(want): return where + ': %r != %r' % (got, want)
    if isinstance(want, dict):
        if set(got) != set(want): return where + ': keys %s != %s' % (sorted(got), sorted(want))
        for k in want:
            d = diff(got[k], want[k], where + '.' + str(k))
            if d: return d
        return None
    if isinstance(want, list):
        if len(got) != len(want): return where + ': %d items != %d' % (len(got), len(want))
        for i, (a, b) in enumerate(zip(got, want)):
            d = diff(a, b, where + '[%d]' % i)
            if d: return d
        return None
    return None if got == want else where + ': %r != %r' % (got, want)
