def parse(scen, page):
    """Recover every placeholder and slot value by walking the page along the pinned template."""
    parts = re.split(r'(\{\{AQ_[A-Z0-9_]+\}\}|<!--AQ:LISTA:[a-z]+-->|<!--AQ:SKRIPT-->)', scen)
    pos, values = 0, {}
    for i, part in enumerate(parts):
        if i % 2 == 0:
            if not page.startswith(part, pos):
                raise AssertionError('page differs from the template near: ' + repr(part[:80]) + ' / page: ' + repr(page[pos:pos + 80]))
            pos += len(part)
            continue
        nxt = parts[i + 1]
        end = page.find(nxt, pos) if nxt else len(page)
        if end < 0:
            raise AssertionError('page lacks the template text after ' + part)
        value = page[pos:end]
        if part in values and values[part] != value:
            raise AssertionError('one placeholder with two values: ' + part)
        values[part] = value
        pos = end
    if pos != len(page):
        raise AssertionError('page continues after the template')
    return values

