def verify(candidate):
    from runtime.profile import sandbox_command, environment
    checks = []
    for name, script in (('projection', PROJECTION), ('scene', SCENE)):
        p = subprocess.run(sandbox_command(Path(candidate), ['/opt/homebrew/bin/python3.12', '-I', '-B', '-c', script]),
                           env=environment(), capture_output=True, text=True, timeout=900)
        if p.returncode:
            return {'passed': False, 'reason': 'Aquarium %s host contract failed' % name, 'stderr': p.stderr[-6000:]}
        try:
            result = json.loads(p.stdout)
        except ValueError:
            return {'passed': False, 'reason': 'Missing host acceptance result for ' + name}
        if result.get('passed') is not True:
            return {'passed': False, 'reason': 'Aquarium %s host contract did not pass' % name}
        checks += result.get('checks', [])
    return {'passed': True, 'checks': checks,
            'scope': 'Schema 2 projection with task-file titles and the rendered work world on synthetic data only; the real page is verified separately by the host'}
